begin;
create table if not exists public.library_source_catalog (id bigint generated by default as identity primary key,entry_group text not null,name text not null,base_url text not null,priority integer not null default 100,official boolean not null default true,created_at timestamptz not null default now(),unique(entry_group,name));
insert into public.library_source_catalog(entry_group,name,base_url,priority) values
('peces','FishBase','https://www.fishbase.se',10),('peces','WoRMS','https://www.marinespecies.org',20),('peces','Catalogue of Life','https://www.catalogueoflife.org',30),('peces','GBIF','https://www.gbif.org',40),('peces','IUCN','https://www.iucnredlist.org',50),('peces','ITIS','https://www.itis.gov',60),('corales','WoRMS','https://www.marinespecies.org',10),('corales','Coral Traits','https://coraltraits.org',20),('corales','Coralpedia','https://coralpedia.bio.warwick.ac.uk',30),('plantas','Plants of the World Online','https://powo.science.kew.org',10),('plantas','GBIF','https://www.gbif.org',20),('plantas','Catalogue of Life','https://www.catalogueoflife.org',30),('microfauna','WoRMS','https://www.marinespecies.org',10),('microfauna','GBIF','https://www.gbif.org',20),('microfauna','Literatura científica','https://scholar.google.com',30),('productos','Fabricante','https://',10),('productos','Ficha técnica','https://',20),('productos','Prospecto oficial','https://',30),('productos','Manual oficial','https://',40),('equipamiento','Fabricante','https://',10),('equipamiento','Manual oficial','https://',20),('equipamiento','Ficha técnica','https://',30)
on conflict(entry_group,name) do update set base_url=excluded.base_url,priority=excluded.priority;
alter table public.library_entries add column if not exists identity_confirmed boolean not null default false,add column if not exists confidence numeric(4,3),add column if not exists identify_result jsonb not null default '{}'::jsonb,add column if not exists sources jsonb not null default '[]'::jsonb,add column if not exists data jsonb not null default '{}'::jsonb,add column if not exists validation_result jsonb not null default '{}'::jsonb,add column if not exists validated_by uuid references auth.users(id) on delete set null;
update public.library_entries set status=case when status='published' and identity_confirmed and jsonb_typeof(sources)='array' and jsonb_array_length(sources)>=2 then 'published' when coalesce(scientific_name,'')<>'' then 'review' else 'identified' end;
alter table public.library_entries drop constraint if exists library_entries_status_check; alter table public.library_entries add constraint library_entries_status_check check(status in('identified','draft','review','validated','published'));
alter table public.library_entries drop constraint if exists library_entries_confidence_check; alter table public.library_entries add constraint library_entries_confidence_check check(confidence is null or(confidence>=0 and confidence<=1));
create table if not exists public.library_audit_log(id uuid primary key default gen_random_uuid(),entry_id uuid,action text not null,user_id uuid references auth.users(id) on delete set null,old_status text,new_status text,created_at timestamptz not null default now(),metadata_json jsonb not null default '{}'::jsonb);
alter table public.library_audit_log enable row level security; alter table public.library_source_catalog enable row level security;
drop policy if exists library_audit_owner_select on public.library_audit_log; create policy library_audit_owner_select on public.library_audit_log for select to authenticated using(exists(select 1 from public.library_entries e where e.id=entry_id and e.user_id=(select auth.uid())));
drop policy if exists library_source_catalog_read on public.library_source_catalog; create policy library_source_catalog_read on public.library_source_catalog for select to authenticated using(true);
grant select on public.library_source_catalog,public.library_audit_log to authenticated; grant select,insert,update,delete on public.library_entries to service_role; revoke insert,delete,truncate,references,trigger on public.library_entries from authenticated,anon; revoke update on public.library_entries from authenticated,anon; grant update(title,scientific_name,entry_type,summary,cover_url,photo_url,sections,tags,ai_prompt,source_notes,data,updated_at) on public.library_entries to authenticated;
create or replace function public.library_real_url_count(input jsonb) returns integer language sql immutable set search_path='' as $$select count(*)::integer from jsonb_array_elements(case when jsonb_typeof(input)='array' then input else '[]'::jsonb end)item where coalesce(item->>'url','')~*'^https?://[^/[:space:]]+\.[^/[:space:]]+'$$;
create or replace function public.library_guard_entry() returns trigger language plpgsql set search_path='' as $$declare is_biological boolean:=new.entry_type=any(array['pez_marino','pez_dulce','coral','invertebrado','planta','microfauna']); approved boolean:=coalesce((new.validation_result->>'approved')::boolean,false); begin if tg_op='UPDATE' and old.status in('validated','published') and(old.title is distinct from new.title or old.scientific_name is distinct from new.scientific_name or old.entry_type is distinct from new.entry_type or old.summary is distinct from new.summary or old.sections is distinct from new.sections or old.data is distinct from new.data or old.sources is distinct from new.sources)then new.status:='review';new.validation_result:=jsonb_build_object('approved',false,'errors',jsonb_build_array('La ficha cambió después de validarse y requiere una nueva auditoría.'),'audited_at',now());approved:=false;end if;if new.status in('draft','review','validated','published')and not new.identity_confirmed then raise exception 'Identificación insuficiente. No se puede crear ficha.';end if;if is_biological and new.status in('draft','review','validated','published')and(coalesce(new.scientific_name,'')!~'^[A-Z][a-z-]+ [a-z][a-z-]+(\s+var\.\s+[a-z-]+)?$' or new.scientific_name~*'\m(spp?|cf|aff)\.?\M')then raise exception 'La ficha biológica requiere una especie concreta.';end if;if new.status in('validated','published')then if public.library_real_url_count(new.sources)<2 then raise exception 'Se requieren al menos dos fuentes con URL real.';end if;if not approved then raise exception 'La ficha no tiene una auditoría aprobada.';end if;end if;if new.status='published' then if tg_op='INSERT' or old.status<>'validated' then raise exception 'Solo se puede publicar una ficha previamente validada.';end if;new.visibility:='public';new.published_at:=coalesce(new.published_at,now());else new.visibility:='private';new.published_at:=null;end if;if new.status='validated' then new.validated_at:=coalesce(new.validated_at,now());elsif new.status not in('published')then new.validated_at:=null;new.validated_by:=null;end if;new.updated_at:=now();return new;end$$;
drop trigger if exists library_guard_entry_trigger on public.library_entries; create trigger library_guard_entry_trigger before insert or update on public.library_entries for each row execute function public.library_guard_entry();
create or replace function public.library_log_change() returns trigger language plpgsql security definer set search_path='' as $$begin if tg_op='INSERT' then insert into public.library_audit_log(entry_id,action,user_id,old_status,new_status,metadata_json)values(new.id,'created',coalesce((select auth.uid()),new.user_id),null,new.status,jsonb_build_object('new',to_jsonb(new),'sources',new.sources,'ai_model',new.ai_model));return new;elsif tg_op='DELETE' then insert into public.library_audit_log(entry_id,action,user_id,old_status,new_status,metadata_json)values(old.id,'deleted',coalesce((select auth.uid()),old.user_id),old.status,null,jsonb_build_object('old',to_jsonb(old),'sources',old.sources,'ai_model',old.ai_model));return old;end if;insert into public.library_audit_log(entry_id,action,user_id,old_status,new_status,metadata_json)values(new.id,case when old.status is distinct from new.status then 'status_changed' else 'updated' end,coalesce((select auth.uid()),new.user_id),old.status,new.status,jsonb_build_object('old',to_jsonb(old),'new',to_jsonb(new),'sources',new.sources,'ai_model',new.ai_model));return new;end$$;
revoke all on function public.library_log_change() from public,anon,authenticated; drop trigger if exists library_log_change_trigger on public.library_entries; create trigger library_log_change_trigger after insert or update or delete on public.library_entries for each row execute function public.library_log_change();
create index if not exists library_entries_status_idx on public.library_entries(status); create index if not exists library_entries_identity_idx on public.library_entries(identity_confirmed); create index if not exists library_audit_entry_created_idx on public.library_audit_log(entry_id,created_at desc);
commit;
